query:
-- Restore teams table to use groupId
ALTER TABLE teams DROP COLUMN IF EXISTS departmentId;
ALTER TABLE teams DROP COLUMN IF EXISTS code;
ALTER TABLE teams ADD COLUMN groupId INT NOT NULL DEFAULT 1 AFTER id;
ALTER TABLE teams MODIFY COLUMN description TEXT NULL;

-- Create companyTeams table
CREATE TABLE IF NOT EXISTS companyTeams (
  id INT AUTO_INCREMENT PRIMARY KEY,
  departmentId INT NOT NULL,
  code VARCHAR(50) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  createdBy INT NOT NULL,
  updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,
  updatedBy INT NOT NULL
);

-- Remove default from groupId
ALTER TABLE teams ALTER COLUMN groupId DROP DEFAULT;

